useSubscription(ON_CHAT_MESSAGE, {
  onError: (error) => {
    if (error.networkError) {
      showToast('Connection lost. Reconnecting...');
    } else if (error.graphQLErrors) {
      error.graphQLErrors.forEach((err) => {
        if (err.extensions?.code === 'FORBIDDEN') {
          showToast('You do not have access to this channel');
        }
      });
    }
  },
});

import { useState, useEffect } from 'react';
import { useSubscription } from '@apollo/client';

function useRetryableSubscription(query, variables, maxRetries = 3) {
  const [retryCount, setRetryCount] = useState(0);
  const [shouldRetry, setShouldRetry] = useState(true);

  const result = useSubscription(query, {
    variables,
    shouldResubscribe: shouldRetry,
    onError: (error) => {
      if (retryCount < maxRetries && error.networkError) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => {
          setRetryCount((c) => c + 1);
          setShouldRetry(true);
        }, delay);
        setShouldRetry(false);
      }
    },
  });

  return result;
}

